const incoming = $json ?? {};
const isWebhook = Boolean(incoming.headers || incoming.query || incoming.params);

return [{
  json: {
    startedAt: new Date().toISOString(),
    trigger: isWebhook ? 'webhook' : 'manual',
    requester: incoming.query?.requester ?? 'reviewer',
    path: incoming.path ?? '/manual-test'
  }
}];

const context = $('Set Run Context').first().json;
const repoItems = $items('Fetch Repo Metadata').map((item) => item.json);
const commitItemsRaw = $items('Fetch Recent Commits').map((item) => item.json);
const repo = repoItems[0] ?? {};
const commitItems = Array.isArray(commitItemsRaw[0]) ? commitItemsRaw[0] : commitItemsRaw;
const commits = commitItems.filter((commit) => commit && !commit.error && commit.sha);
const uniqueCommits = [...new Map(commits.map((commit) => [commit.sha, commit])).values()].slice(0, 5);
const apiFailed = Boolean(repo.error || repo.message === 'Not Found' || commitItemsRaw.some((item) => item?.error));
const pushedAt = repo.pushed_at ? new Date(repo.pushed_at) : null;
const hoursSincePush = pushedAt ? Math.max(0, Math.round((Date.now() - pushedAt.getTime()) / 36e5)) : null;
const staleRepo = hoursSincePush !== null && hoursSincePush > 72;
const missingCommits = uniqueCommits.length === 0;
const needsAttention = apiFailed || staleRepo || missingCommits;
const score = apiFailed
  ? 45
  : Math.max(70, Math.min(100, 100 - Math.max(0, hoursSincePush ?? 0) - Math.max(0, 5 - uniqueCommits.length) * 4));
const status = needsAttention ? 'ATTENTION' : 'READY';
const recentCommits = uniqueCommits.map((commit) => ({
  sha: commit.sha.slice(0, 7),
  message: (commit.commit?.message ?? 'No commit message').split('\n')[0],
  author: commit.commit?.author?.name ?? 'unknown',
  date: commit.commit?.author?.date ?? null,
  url: commit.html_url
}));
const checks = [
  {
    name: 'GitHub API reachable',
    passed: !apiFailed,
    detail: apiFailed ? 'GitHub returned an error or incomplete payload.' : 'Repository metadata and commits were returned.'
  },
  {
    name: 'Recent commit activity',
    passed: !staleRepo && hoursSincePush !== null,
    detail: hoursSincePush === null ? 'No push timestamp found.' : `${hoursSincePush} hours since last push.`
  },
  {
    name: 'Commit list usable',
    passed: !missingCommits,
    detail: `${uniqueCommits.length} recent commits available for review.`
  }
];
const markdownReport = [
  '## Alba Submission Health Report',
  `Status: ${status}`,
  `Score: ${score}`,
  `Repository: ${repo.full_name ?? 'kunal-gh/alba-vibe-assessment'}`,
  `Default branch: ${repo.default_branch ?? 'unknown'}`,
  `Last push: ${repo.pushed_at ?? 'unknown'}`,
  '',
  '### Checks',
  ...checks.map((check) => `- ${check.passed ? 'PASS' : 'ATTENTION'}: ${check.name} - ${check.detail}`),
  '',
  '### Recent commits',
  ...recentCommits.map((commit) => `- ${commit.sha}: ${commit.message}`)
].join('\n');

return [{
  json: {
    workflow: 'Alba Submission Health Report',
    status,
    score,
    severity: needsAttention ? 'review' : 'normal',
    generatedAt: new Date().toISOString(),
    trigger: context.trigger,
    requester: context.requester,
    repository: repo.full_name ?? 'kunal-gh/alba-vibe-assessment',
    repositoryUrl: repo.html_url ?? 'https://github.com/kunal-gh/alba-vibe-assessment',
    defaultBranch: repo.default_branch ?? 'unknown',
    lastPush: repo.pushed_at ?? null,
    hoursSincePush,
    recentCommitCount: uniqueCommits.length,
    recentCommits,
    checks,
    markdownReport
  }
}];

return items.map((item) => ({
  json: {
    ...item.json,
    headline: 'Repository activity is current and the submission package is ready for final manual review.',
    recommendedAction: 'Open the deployed URLs, record Loom, then submit.'
  }
}));

return items.map((item) => ({
  json: {
    ...item.json,
    headline: 'One or more readiness checks need attention before submission.',
    recommendedAction: 'Review the failed checks, then rerun this workflow.'
  }
}));
